import { mkdtempSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { pathToFileURL } from "node:url"

import { afterEach, describe, expect, it, vi } from "vitest"

import {
  EDITOR_PORTS,
  PUBLIC_SITE_PORTS,
  resolveDevPorts,
} from "./dev-ports.ts"

const WORKTREE_ENV = [
  "# Generated by scripts/worktree/worktree.sh — slot 3. Do not commit.",
  "WORKTREE_SLOT=3",
  "DEV_PORT=21030",
  "PREVIEW_PORT=21031",
  "SITE_DEV_PORT=21032",
  "SITE_PREVIEW_PORT=21033",
  "",
].join("\n")

const APPS = [
  {
    name: "the editor",
    app: EDITOR_PORTS,
    defaults: { dev: 5173, preview: 4173 },
    fromFile: { dev: 21030, preview: 21031 },
    variables: ["DEV_PORT", "PREVIEW_PORT"],
  },
  {
    name: "the public site",
    app: PUBLIC_SITE_PORTS,
    defaults: { dev: 5174, preview: 4174 },
    fromFile: { dev: 21032, preview: 21033 },
    variables: ["SITE_DEV_PORT", "SITE_PREVIEW_PORT"],
  },
] as const

describe("resolveDevPorts", () => {
  let directory: string | undefined

  afterEach(() => {
    vi.unstubAllEnvs()
    if (directory) rmSync(directory, { recursive: true, force: true })
    directory = undefined
  })

  function envFile(contents?: string): URL {
    directory = mkdtempSync(join(tmpdir(), "dev-ports-"))
    const path = join(directory, ".env.worktree")
    if (contents !== undefined) writeFileSync(path, contents)
    return pathToFileURL(path)
  }

  it.each(APPS)(
    "keeps $name's default ports outside a parallel worktree",
    ({ app, defaults }) => {
      expect(resolveDevPorts(app, envFile())).toEqual(defaults)
    },
  )

  it.each(APPS)(
    "reads $name's own ports from the shared .env.worktree",
    ({ app, fromFile }) => {
      expect(resolveDevPorts(app, envFile(WORKTREE_ENV))).toEqual(fromFile)
    },
  )

  it.each(APPS)(
    "ignores $name's ambient port variables",
    ({ app, defaults, variables }) => {
      for (const variable of variables) vi.stubEnv(variable, "1234")

      expect(resolveDevPorts(app, envFile())).toEqual(defaults)
    },
  )

  it.each(
    APPS.flatMap(({ name, app, variables: [dev, preview] }) => [
      {
        name,
        app,
        variable: dev,
        fault: "a missing port",
        text: `${preview}=21031\n`,
      },
      {
        name,
        app,
        variable: preview,
        fault: "a port out of range",
        text: `${dev}=21030\n${preview}=70000\n`,
      },
      {
        name,
        app,
        variable: preview,
        fault: "a port that is not a number",
        text: `${dev}=21030\n${preview}=abc\n`,
      },
      {
        name,
        app,
        variable: dev,
        fault: "a file that predates its ports",
        text: "WORKTREE_SLOT=3\n",
      },
    ]),
  )(
    "rejects $fault for $name, naming $variable and the fix",
    ({ app, variable, text }) => {
      expect(() => resolveDevPorts(app, envFile(text))).toThrow(
        `.env.worktree has no valid ${variable}; rerun pnpm worktree:setup to rewrite it`,
      )
    },
  )
})
